396	<body>
397	  <main>
398	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
399	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
400	        <circle cx="200" cy="200" r="200"/>
401	      </svg>
402	    </button>
403	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
404	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
405	    <div class="controls" role="group" aria-label="Circle controls">
406	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
407	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
408	    </div>
409	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
410	  </main>
411	
412	  <script defer>
413	    const CONFIG = {
414	      storageKey: 'circle-state',
415	      tapDelay: 300,
416	      colorShiftDuration: 500,
417	      colorModes: [
418	        { class: 'default', name: 'Default White' },
419	        { class: 'color-mode-1', name: 'Pink' },
420	        { class: 'color-mode-2', name: 'Teal' },
421	        { class: 'color-mode-3', name: 'Mint' },
422	        { class: 'color-mode-4', name: 'Purple' },
423	        { class: 'color-mode-5', name: 'Orange' }
424	      ],
425	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
426	      pulseInterval: 2500
427	    };
428	
429	    const el = {
430	      circle: document.getElementById('decorative-circle'),
431	      hint: document.getElementById('hint-text'),
432	      modeIndicator: document.getElementById('mode-indicator'),
433	      cycleBtn: document.getElementById('cycle-btn'),
434	      resetBtn: document.getElementById('reset-btn')
435	    };
436	
437	    let state = { active: false, colorMode: 0 };
438	    let tapCount = 0;
439	    let tapTimeout = null;
440	    let animatingColorShift = false;
441	
442	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
443	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
444	
445	    const storage = {
446	      save() {
447	        try {
448	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
449	        } catch {
450	          // Silently fail if localStorage is unavailable or quota exceeded
451	        }
452	      },
453	      load() {
454	        try {
455	          const saved = localStorage.getItem(CONFIG.storageKey);
456	          if (saved) {
457	            const parsed = JSON.parse(saved);
458	            if (parsed && typeof parsed === 'object') {
459	              state = { ...state, ...parsed };
460	            }
461	          }
462	        } catch {
463	          // Silently fail if parsing fails
464	        }
465	      }
466	    };
467	
468	    const updateClasses = () => {
469	      const colorClasses = CONFIG.colorModes.map(m => m.class);
470	      el.circle.classList.remove('active', ...colorClasses);
471	      el.circle.setAttribute('aria-pressed', state.active);
472	      if (state.active) el.circle.classList.add('active');
473	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
474	    };
475	
476	    const updateUI = () => {
477	      let hintText = '';
478	
479	      if (CONFIG.isTouch) {
480	        hintText = state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle';
481	      } else {
482	        hintText = state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle';
483	      }
484	
485	      el.hint.textContent = hintText;
486	
487	      const showMode = state.active && state.colorMode > 0;
488	      el.modeIndicator.classList.toggle('visible', showMode);
489	      if (showMode) {
490	        const modeName = getColorModeName(state.colorMode);
491	        el.modeIndicator.textContent = `◆ ${modeName.toUpperCase()}`;
492	      }
493	    };
494	
495	    const applyState = () => {
496	      updateClasses();
497	      updateUI();
498	    };
499	
500	    const toggleActive = () => {
501	      state.active = !state.active;
502	      applyState();
503	      storage.save();
504	    };
505	
506	    const cycleColor = () => {
507	      if (animatingColorShift) return;
508	      animatingColorShift = true;
509	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
510	      state.active = true;
511	      el.circle.classList.add('color-shifting');
512	      setTimeout(() => {
513	        el.circle.classList.remove('color-shifting');
514	        animatingColorShift = false;
515	      }, CONFIG.colorShiftDuration);
516	      applyState();
517	      storage.save();
518	    };
519	
520	    const resetState = () => {
521	      state = { active: false, colorMode: 0 };
522	      applyState();
523	      storage.save();
524	    };
525	
526	    const handleClick = () => {
527	      if (!CONFIG.isTouch) toggleActive();
528	    };
529	
530	    const handleDblClick = () => {
531	      cycleColor();
532	    };
533	
534	    const handleTouchEnd = () => {
535	      tapCount++;
536	      clearTimeout(tapTimeout);
537	      if (tapCount === 1) {
538	        tapTimeout = setTimeout(() => {
539	          if (tapCount === 1) toggleActive();
540	          tapCount = 0;
541	        }, CONFIG.tapDelay);
542	      } else if (tapCount === 2) {
543	        cycleColor();
544	        tapCount = 0;
545	      }
546	    };
547	
548	    const keyHandlers = {
549	      ' ': toggleActive,
550	      'enter': toggleActive,
551	      'c': cycleColor,
552	      'r': resetState
553	    };
554	
555	    const handleKeyDown = (e) => {
556	      const handler = keyHandlers[e.key.toLowerCase()];
557	      if (handler) {
558	        e.preventDefault();
559	        handler();
560	      }
561	    };
562	
563	    const initListeners = () => {
564	      if (CONFIG.isTouch) {
565	        el.circle.addEventListener('touchend', handleTouchEnd);
566	      } else {
567	        el.circle.addEventListener('click', handleClick);
568	        el.circle.addEventListener('dblclick', handleDblClick);
569	      }
570	      el.circle.addEventListener('blur', () => {
571	        tapCount = 0;
572	        clearTimeout(tapTimeout);
573	      });
574	      document.addEventListener('keydown', handleKeyDown);
575	      el.cycleBtn.addEventListener('click', cycleColor);
576	      el.resetBtn.addEventListener('click', resetState);
577	    };
578	
579	    const initApp = () => {
580	      storage.load();
581	      applyState();
582	      initListeners();
583	      el.circle.focus();
584	    };
585	
586	    if (document.readyState === 'loading') {
587	      document.addEventListener('DOMContentLoaded', initApp);
588	    } else {
589	      initApp();
590	    }
591	  </script>
592	</body>
593	</html>
